const timelineCommandButtons=document.createElement('span');timelineCommandButtons.style.display='contents';timelineCommandButtons.innerHTML='<button id="timelineEditClip">Edit clip</button><button id="timelineDuplicateClip" title="Duplicate selected clip · Ctrl+D">Duplicate</button><button id="timelineDeleteClip" title="Delete selected clip · Delete">Delete</button><button id="timelineShortcuts">Keyboard shortcuts</button>';document.querySelector('.timeline-top').prepend(timelineCommandButtons);
const shortcutCards=[['Delete / Backspace','Delete the selected timeline clip'],['Ctrl + D','Duplicate the selected clip next to it'],['Ctrl + C','Copy a visual, audio or caption clip'],['Ctrl + V','Paste a copied clip at the playhead'],['Ctrl + B','Split a visual or audio clip at the playhead'],['Shift + Delete','Ripple delete within the current scene'],['Ctrl + Z','Undo'],['Ctrl + Shift + Z','Redo'],['Space','Play / pause'],['?','Show these keyboard shortcuts'],['Right-click a clip','Open its editing menu'],['Drag / drag an edge','Move a clip / trim its start or end']];
document.body.insertAdjacentHTML('beforeend','<dialog id="timelineShortcutDialog"><div class="tool-heading"><h2>Keyboard shortcuts</h2><button id="closeTimelineShortcuts">Close</button></div><p class="note">Select a clip on the bottom timeline first. Editing keys are paused while you type or use a dialog. On Mac, use Command in place of Ctrl.</p><div class="shortcut-cards"></div><p class="note">Duplicate places the copy after the original if there is room. For a full scene, use Copy scene next or Continue scene. Ripple delete shifts later clips within this scene; its duration stays fixed.</p></dialog>');
