$('timelineShortcuts').onclick=()=>{clipMenu.hidden=true;$('timelineShortcutDialog').showModal()};$('closeTimelineShortcuts').onclick=()=>$('timelineShortcutDialog').close();$('timelineBody').tabIndex=0;
function timelineTarget(){
 const t=timelineSelection;if(!t)return null;
 if(t.kind==='scene')return project.scenes.find(s=>s.id===t.id)||null;
 if(t.kind==='audio')return tracks().find(c=>c.id===t.id)||null;
 const owner=project.scenes.find(s=>s.id===t.sceneId);if(!owner)return null;
 return t.kind==='caption'?(owner.captions||[])[t.index]||null:owner.objects.find(o=>o.id===t.id)||null;
}
function chooseTimelineClip(t){stop();if(t.sceneId&&t.sceneId!==current().id){sceneIndex=project.scenes.findIndex(s=>s.id===t.sceneId);time=0;}timelineSelection=t;if(t.kind==='scene'){sceneIndex=project.scenes.findIndex(s=>s.id===t.id);time=0;selectLayers([]);selectedAudio=null}else if(t.kind==='audio'){selectLayers([]);selectedAudio=t.id}else if(t.kind==='visual'){selectLayers([t.id]);selectedAudio=null}else{selectLayers([]);selectedAudio=null}render();$('timelineBody').focus({preventScroll:true})}
function ensureTimelineEdit(){if(recording||window.editorTaskBusy||audioBusy)throw Error('Finish the current media task first.');const target=timelineTarget();if(target&&timelineSelection.sceneId&&current().id!==timelineSelection.sceneId){sceneIndex=project.scenes.findIndex(s=>s.id===timelineSelection.sceneId);time=0;}if(!target)throw Error('Select a clip on the timeline first.');if(target.locked)throw Error('Unlock this layer before editing.');return target}
function commitTimelineDraft(draft){if(!valid(draft))throw Error('This edit does not fit the project. Nothing was changed.');stop();project=draft;sceneIndex=Math.min(sceneIndex,project.scenes.length-1);time=Math.min(time,current().duration);selectLayers([]);selectedAudio=null;timelineSelection=null;normalizeLinkedMedia();save();render();hydrateAudio()}
function deleteTimelineClip(){
 const target=ensureTimelineEdit(),kind=timelineSelection.kind,draft=structuredClone(project),s=draft.scenes[sceneIndex];
 if(kind==='scene'){
  if(draft.scenes.length===1)throw Error('Keep at least one scene. You can delete its individual clips.');
  const index=draft.scenes.findIndex(x=>x.id===target.id),a=draft.scenes.slice(0,index).reduce((n,x)=>n+x.duration,0),b=a+target.duration,next=[];
  for(const c of draft.audioClips||[]){const end=audioEnd(c);if(end<=a){next.push(c);continue}if(c.start>=b){c.start-=target.duration;next.push(c);continue}if(c.start<a){const left={...c,duration:a-c.start,fadeOut:0};next.push(left)}if(end>b){const right={...c,id:c.start<a?uid():c.id,start:a,offset:c.offset+(b-c.start)*(c.rate||1),duration:end-b,fadeIn:0};next.push(right)}}
  draft.scenes.splice(index,1);draft.audioClips=next;draft.markers=(draft.markers||[]).filter(m=>m.time<a||m.time>=b).map(m=>({...m,time:m.time>=b?m.time-target.duration:m.time}));
 }else if(kind==='audio')draft.audioClips=draft.audioClips.filter(c=>c.id!==target.id);
 else if(kind==='caption')s.captions.splice(timelineSelection.index,1);
 else{s.objects=s.objects.filter(o=>o.id!==target.id);draft.audioClips=(draft.audioClips||[]).filter(c=>c.videoId!==target.id);s.propInteractions=(s.propInteractions||[]).filter(e=>![e.actorId,e.propId,e.otherId].includes(target.id))}
 commitTimelineDraft(draft);toast('Deleted. Ctrl+Z restores the edit.');
}
function copyTimelineClip(){const target=ensureTimelineEdit(),kind=timelineSelection.kind;if(kind==='scene')throw Error('Use Copy scene next to duplicate a complete scene.');timelineClipboard={kind,item:structuredClone(target),sceneDuration:current().duration,audio:kind==='visual'?structuredClone(tracks().filter(c=>c.videoId===target.id)):[]};toast('Clip copied. Move the playhead and paste with Ctrl+V.')}
function shiftCopiedVisual(o,delta,duration){
 const shift=keys=>{for(const k of keys||[])k.t=clamp(k.t+delta,0,duration)};
 for(const key of ['keys','expressionKeys','viewKeys','handGestureKeys'])shift(o[key]);
 for(const track of Object.values(o.bodyAnimation||{}))shift(track.keys);
 for(const keys of Object.values(o.objectAnimation||{}))shift(keys);
 for(const block of o.actionBlocks||[]){block.id=uid();block.start+=delta;if(block.start<0||block.start+block.duration>duration+.001)throw Error('This animation needs more room. Extend the scene or use Copy scene next.')}
 for(const pin of o.footPins||[]){if(Number.isFinite(pin.start))pin.start+=delta;if(Number.isFinite(pin.end))pin.end+=delta}
 if(o.motionPath){for(const key of ['start','end'])if(Number.isFinite(o.motionPath[key]))o.motionPath[key]+=delta}
 if(o.wordAnimation?.words)for(const w of o.wordAnimation.words){w.start+=delta;w.end+=delta}
 for(const key of ['continuityId','continuitySource','dialogueLineId','exitTransition'])delete o[key];
}
function pasteTimelineClip(at=time,audioAt=globalTime()){
 if(recording||window.editorTaskBusy||audioBusy)throw Error('Finish the current media task first.');if(!timelineClipboard)throw Error('Copy a clip first.');
 const {kind,item,audio}=timelineClipboard,draft=structuredClone(project),s=draft.scenes[sceneIndex],copy=structuredClone(item);copy.id=uid();
 if(kind==='audio'){if(audioAt+copy.duration>totalDuration()+.001)throw Error('There is no room after this clip. Add or extend a scene first.');copy.start=audioAt;delete copy.videoId;(draft.audioClips??=[]).push(copy)}
 else if(kind==='caption'){const delta=at-copy.start;copy.start=at;copy.end+=delta;if(copy.end>s.duration+.001)throw Error('Extend the scene to make room for this caption.');for(const w of copy.words||[]){w.start+=delta;w.end+=delta}(s.captions??=[]).push(copy)}
 else{const start=item.in??0,end=item.out??timelineClipboard.sceneDuration,delta=at-start;if(at<0||at+end-start>s.duration+.001)throw Error('There is no room after this clip. Extend the scene or use Copy scene next.');copy.in=at;copy.out=at+end-start;copy.name+=' · copy';shiftCopiedVisual(copy,delta,s.duration);s.objects.push(copy);for(const a of audio){const c=structuredClone(a);c.id=uid();c.videoId=copy.id;c.start=sceneOffset()+at;(draft.audioClips??=[]).push(c)}}
 commitTimelineDraft(draft);timelineSelection={kind,id:copy.id,sceneId:current().id,index:kind==='caption'?current().captions.length-1:undefined};if(kind==='visual')selectLayers([copy.id]);if(kind==='audio')selectedAudio=copy.id;render();toast('Copy added to the timeline.');
}
async function duplicateTimelineClip(){const target=ensureTimelineEdit();if(timelineSelection.kind==='scene')return copyTimelineScene(project.scenes.indexOf(target));const kind=timelineSelection.kind,at=kind==='audio'?audioEnd(target):kind==='caption'?target.end:clipEnd(target);copyTimelineClip();pasteTimelineClip(at,at)}
function editTimelineClip(){const target=ensureTimelineEdit(),kind=timelineSelection.kind;if(kind==='scene'){$('sceneName').focus();$('sceneName').select()}else if(kind==='caption'){const next=prompt('Caption text',target.text);if(next!==null){target.text=next;save();render()}}else if(kind==='audio')$('clipSettings').querySelector('input')?.focus();else{renderControls();const input=$('controls').querySelector('input:not([disabled]),textarea:not([disabled]),select:not([disabled])');input?.focus();input?.scrollIntoView({block:'nearest'})}}
async function runTimelineCommand(action){clipMenu.hidden=true;try{if(action==='paste')pasteTimelineClip();else if(action==='copy')copyTimelineClip();else if(action==='duplicate')await duplicateTimelineClip();else if(action==='delete')deleteTimelineClip();else if(action==='edit')editTimelineClip();else if(action==='continue'){ensureTimelineEdit();await copyTimelineScene(sceneIndex,true)}else if(action==='split'){ensureTimelineEdit();if(!['visual','audio'].includes(timelineSelection.kind))throw Error('Select a visual or audio clip to split.');$('splitClip').click()}else if(action==='ripple'){ensureTimelineEdit();if(!['visual','audio'].includes(timelineSelection.kind))throw Error('Ripple delete works on visual and audio clips.');rippleRemoveSelection()}}catch(e){toast(e.message)}}
for(const [id,action]of [['timelineEditClip','edit'],['timelineDuplicateClip','duplicate'],['timelineDeleteClip','delete']])$(id).onclick=()=>runTimelineCommand(action);
const splitBeforeTimelineCommands=$('splitClip').onclick;$('splitClip').onclick=()=>{splitBeforeTimelineCommands();if(timelineSelection&&selectedAudio)timelineSelection={kind:'audio',id:selectedAudio};else if(timelineSelection&&selected)timelineSelection={kind:'visual',id:selected,sceneId:current().id};renderTimeline()};
function openTimelineMenu(e,t){e.preventDefault();e.stopPropagation();chooseTimelineClip(t);clipMenu.replaceChildren();const entries=t.kind==='scene'?[['edit','Edit scene',''],['duplicate','Copy scene next','Ctrl+D'],['continue','Continue scene',''],['delete','Delete scene','Delete']]:[['edit','Edit clip',''],['copy','Copy','Ctrl+C'],['paste','Paste at playhead','Ctrl+V'],['duplicate','Duplicate next','Ctrl+D'],...(['visual','audio'].includes(t.kind)?[['split','Split at playhead','Ctrl+B'],['ripple','Ripple delete','Shift+Del']]:[]),['delete','Delete','Delete']];for(const [action,label,key]of entries){const b=document.createElement('button');b.setAttribute('role','menuitem');b.textContent=label;const k=document.createElement('kbd');k.textContent=key;b.append(k);b.onclick=()=>runTimelineCommand(action);clipMenu.append(b)}clipMenu.hidden=false;clipMenu.style.left=Math.max(0,Math.min(e.clientX,innerWidth-230))+'px';clipMenu.style.top=Math.max(0,Math.min(e.clientY,innerHeight-clipMenu.offsetHeight-8))+'px';clipMenu.querySelector('button')?.focus()}
const makeClipBeforeCommands=makeClip;makeClip=function(area,options){const el=makeClipBeforeCommands(area,options);if(options.audioClip)el.dataset.audioId=options.audioClip.id;return el};
const renderBeforeTimelineCommands=renderTimeline;renderTimeline=function(){renderBeforeTimelineCommands();let captionIndex=0;document.querySelectorAll('.timeline-clip').forEach(el=>{let target;if(el.dataset.sceneIndex!==undefined)target={kind:'scene',id:project.scenes[+el.dataset.sceneIndex].id};else if(el.dataset.objectId)target={kind:'visual',id:el.dataset.objectId,sceneId:el.dataset.ownerSceneId||current().id};else if(el.dataset.audioId)target={kind:'audio',id:el.dataset.audioId};else if(el.classList.contains('caption'))target={kind:'caption',index:+el.dataset.captionIndex||0,sceneId:el.dataset.ownerSceneId||current().id};if(!target)return;el.classList.toggle('command-selected',JSON.stringify(target)===JSON.stringify(timelineSelection));el.oncontextmenu=e=>openTimelineMenu(e,target);el.addEventListener('pointerdown',e=>{if(recording)return;timelineSelection=target;$('timelineBody').focus({preventScroll:true});if(e.button!==0){e.stopImmediatePropagation();e.preventDefault()}},true);el.ondblclick=()=>{chooseTimelineClip(target);runTimelineCommand('edit')}});const exists=!!timelineTarget();for(const id of ['timelineEditClip','timelineDuplicateClip','timelineDeleteClip'])$(id).disabled=!exists||recording};
document.addEventListener('pointerdown',e=>{if(!clipMenu.contains(e.target))clipMenu.hidden=true;if(!e.target.closest('.timeline,#timelineClipMenu'))timelineSelection=null},true);
document.addEventListener('keydown',e=>{
 if(e.target.closest('input,textarea,select,[contenteditable="true"]')||document.querySelector('dialog[open]')||recording)return;
 if(e.key==='Escape'&&!clipMenu.hidden){clipMenu.hidden=true;$('timelineBody').focus();return}
 if(e.key==='?'){e.preventDefault();e.stopImmediatePropagation();$('timelineShortcuts').click();return}
 if(!timelineSelection&&!e.target.closest('.timeline'))return;
 const mod=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();let command=null;
 if(['Delete','Backspace'].includes(e.key))command=e.shiftKey?'ripple':'delete';else if(mod)command=({c:'copy',v:'paste',d:'duplicate',b:'split'})[k];
 if(command){e.preventDefault();e.stopImmediatePropagation();runTimelineCommand(command)}
},true);
